const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Africa geometry
  const africa = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('wld_rgn', 'Africa'));

  // Get MODIS Land Cover data (MCD12Q1) for cropland classification
  // IGBP classification: class 12 = Croplands
  const landCover2003 = ee.Image('MODIS/051/MCD12Q1/2003_01_01')
    .select('Land_Cover_Type_1');
  const landCover2019 = ee.Image('MODIS/006/MCD12Q1/2019_01_01')
    .select('LC_Type1');

  // Create cropland masks (class 12)
  const cropland2003 = landCover2003.eq(12);
  const cropland2019 = landCover2019.eq(12);

  // Calculate area in square kilometers
  const area2003 = cropland2003.multiply(ee.Image.pixelArea()).divide(1e6);
  const area2019 = cropland2019.multiply(ee.Image.pixelArea()).divide(1e6);

  // Reduce regions to get total area
  const stats2003 = area2003.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: africa,
    scale: 1000,
    maxPixels: 1e12
  });

  const stats2019 = area2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: africa,
    scale: 1000,
    maxPixels: 1e12
  });

  // Get results
  const area2003Val = stats2003.get('Land_Cover_Type_1').getInfo();
  const area2019Val = stats2019.get('LC_Type1').getInfo();
  const difference = area2019Val - area2003Val;

  // Print evidence
  console.log(`2003 Cropland Area: ${area2003Val.toFixed(0)} km²`);
  console.log(`2019 Cropland Area: ${area2019Val.toFixed(0)} km²`);
  console.log(`Difference: ${difference.toFixed(0)} km²`);

  // Validate and determine answer
  if (area2003Val === null || area2019Val === null) {
    console.log("<answer>C3</answer>");
  } else if (difference > 400000) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
